   453→        private static void CheckBlurSprite()
   454→        {
   455→            List<int> nul = new List<int>();
   456→            for (int i = graphs.Count - 1; i >= 0; i--)
   457→            {
   458→                if (graphs[i] == null)
   459→                {
   460→                    nul.Add(i);
   461→                }
   462→            }
   463→            foreach (var it in nul)//删除空的背景
   464→            {
   465→                graphs.RemoveAt(it);
   466→            }
   467→            for (int i = 0; i < graphs.Count; i++)//显示最后一个虚化组件
   468→            {
   469→                graphs[i].setVisible(i == graphs.Count - 1);
   470→            }
   471→        }
