   476→        /// </summary>
   477→        /// <param name="father"></param>
   478→        public void createBackBlurSprite()
   479→        {
   480→            if (!PopupViewController.getInstance().useStaticBlur)
   481→            {
   482→                getScreenShotBlurBgOld();
   483→            }
   484→            //StartCoroutine(getScreenShotBlurBgNewTexture());
