   547→            blurBGNew.setPosition(Vector2.zero);
   548→            blurBGNew.SetSize(GRoot.inst.width * ScreenAdaptation.cameraRect.width,
   549→                GRoot.inst.height * ScreenAdaptation.cameraRect.height);
   550→            blurBGNew.AddRelation(this._mainView, RelationType.Size);
   551→            blurBGNew.texture = new NTexture(shotTexture);
   552→        }
